      if(Set.of("POS","ISSUE").contains(type))exception|=net.compareTo(inventory.average(t,wh,skuId).multiply(base))<0;
      String condition=text(l,"condition","GOOD");if(!Set.of("GOOD","OPENED","USED","FAULTY","QUARANTINE").contains(condition))throw problem("INVALID_CONDITION","Tình trạng hàng không hợp lệ");
      if(type.equals("SALE_RETURN")){if(condition.equals("FAULTY")||condition.equals("USED"))throw problem("WARRANTY_REQUIRED","Hàng lỗi/đã sử dụng cần tiếp nhận bảo hành");if(condition.equals("OPENED")&&!snap.path("allow_opened").asBoolean())throw problem("RETURN_CONDITION","Sản phẩm không cho trả khi đã mở bao bì");int days=snap.path("return_days").asInt();if(days==0)throw problem("RETURN_NOT_ALLOWED","Sản phẩm không áp dụng trả hàng");var posted=((java.sql.Timestamp)sourceDoc.get("posted_at")).toInstant().atZone(java.time.ZoneId.of("Asia/Ho_Chi_Minh")).toLocalDate();if(today().isAfter(posted.plusDays(days)))metadata.put("overdueReturn",true);}
