      r.db.update("insert into retail.line(tenant_id,document_id,sku_id,source_line_id,position,sku_snapshot,unit,ratio,qty,base_qty,price,discount,vat,net,tax,total,lot,expiry,serials,condition,rule_snapshot,counted_qty) values(?,?,?,?,?,?::jsonb,?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?::jsonb,?)",t,id,skuId,sourceLine,position++,snap.toString(),unit,ratio,qty,base,price,discount,vat,net,tax,lineTotal,lot,expiry,serials.toString(),condition,r.json.valueToTree(priceInfo).toString(),type.equals("COUNT")?quantity(num(l,"countedQty",BigDecimal.ZERO)):null);
